  function bankDateSortKey(value){const text=String(value??'').trim(),iso=text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/),uk=text.match(/^(\d{1,2})[/. -](\d{1,2})[/. -](\d{4})$/);let year,month,day;if(iso){year=Number(iso[1]);month=Number(iso[2]);day=Number(iso[3]);}else if(uk){day=Number(uk[1]);month=Number(uk[2]);year=Number(uk[3]);}else return null;const timestamp=Date.UTC(year,month-1,day),date=new Date(timestamp);return date.getUTCFullYear()===year&&date.getUTCMonth()===month-1&&date.getUTCDate()===day?timestamp:null;}
