    const accepted=rows.filter(row=>!row.rejected),rejected=rows.filter(row=>row.rejected),sumCents=items=>items.reduce((sum,row)=>sum+(amountCents(row)??0),0),missing=rejected.filter(row=>amountCents(row)===null).length;
